gesamthypothek_regress_restverteilung <- function(gesamthypothekenbetrag=NULL, uebergegangener_regressbetrag=NULL, grundstuecke=NULL, ersatzpflichtiges_grundstueck_id=NULL, verteilungsmodell=NULL, methodennachweis=NULL) {
 gesamt <- .geld(gesamthypothekenbetrag);regress <- .geld(uebergegangener_regressbetrag);name <- .text(ersatzpflichtiges_grundstueck_id,'ersatzpflichtiges_grundstueck_id');.auswahl(verteilungsmodell,'verteilungsmodell',c('restquotierung_mit_anteiliger_restzuweisung'));.text(methodennachweis,'methodennachweis')
 if(.vergleichen(regress,gesamt)>0) .fehler('uebergegangener_regressbetrag','Teil\u00fcbergang h\u00f6chstens Gesamtbetrag.')
 rest <- .subtrahieren(gesamt,regress);basis <- gesamthypothek_nichtnegative_nettowertanteile(.bruchteile(rest),grundstuecke,'positive_nettowerte',methodennachweis)$wert
 if(!basis$quoten_bestimmbar) .fehler('grundstuecke','Keine positive Quotierungsbasis; Nettowertdiagnose separat verwenden.')
 namen <- vapply(basis$anteile,function(p)p$grundstueck_id,character(1))
 if(!name %in% namen) .fehler('ersatzpflichtiges_grundstueck_id','Grundst\u00fcck muss enthalten sein.')
 i <- match(name,namen);quote <- basis$anteile[[i]]$anteilsquote;anrechnung <- gesamthypothek_regressanrechnung(.bruchteile(rest),quote,.bruchteile(regress),methodennachweis)$wert;eigen <- .geld(anrechnung$verbleibender_anteil);offen <- .subtrahieren(rest,eigen)
 gewichte <- lapply(seq_along(namen),function(j)if(j==i).bruch(0) else .geld(basis$nettowerte[[j]]$verteilungsgewicht))
 verteilung <- .begrenzte_quotenverteilung(offen,gewichte,lapply(gewichte,function(g)offen));anteile <- verteilung$zugeordnet;anteile[[i]] <- eigen
 wert <- list(uebergegangener_regressbetrag=.bruchteile(regress),verbleibende_gemeinschaftsmasse=.bruchteile(rest),eigentuemeranteile=lapply(seq_along(namen),function(j)list(grundstueck_id=namen[[j]],hypothekenanteil=.bruchteile(anteile[[j]]))),nicht_zugewiesener_restbetrag=.bruchteile(verteilung$rest))
 eingaben <- list(gesamthypothekenbetrag=gesamthypothekenbetrag, uebergegangener_regressbetrag=uebergegangener_regressbetrag, grundstuecke=grundstuecke, ersatzpflichtiges_grundstueck_id=ersatzpflichtiges_grundstueck_id, verteilungsmodell=verteilungsmodell, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_GESAMTHYPOTHEK_REGRESS_RESTVERTEILUNG",eingaben,list(list(operation="Teil\u00fcbergang abziehen,1174-Anrechnung auf Restquote ausf\u00fchren und \u00fcbrige Masse unter ausdr\u00fccklich vorgegebenem Modell den anderen Eigent\u00fcmern proportional zuweisen.")),eingaben)
 ergebnis$hinweise <- list("Bedingtes vollst\u00e4ndiges Rechenmodell: Restmasse=Gesamtbetrag-Regress\u00fcbergang.1172-Nettogewichte mit vorhandener positiver Nettowertmethode bestimmen.1174II-Anrechnung des \u00dcbergangs auf den quotierten Restanteil des ersatzpflichtigen Eigent\u00fcmers durch vorhandenen Anrechnungskern. Verbleibende Restmasse proportional nach positiven Nettogewichten der \u00fcbrigen Eigent\u00fcmer verteilen. Dieses zus\u00e4tzliche Zuweisungsmodell ist eine ausdr\u00fccklich zu qualifizierende Voraussetzung, keine aus dem Normwortlaut allein gesicherte generelle Auslegung. Ohne andere positive Gewichte bleibt der nicht zuweisbare Betrag sichtbar; keine k\u00fcnstliche Kopfquote oder R\u00fcckzuweisung entgegen der gew\u00e4hlten Anrechnung. Bei v\u00f6llig fehlender positiver Nettowertbasis Eingabe ablehnen und separate Nettowertdiagnose verwenden. Summe \u00dcbergang+Eigent\u00fcmeranteile+nichtzugewiesen=Gesamtbetrag.1176/1182-Rangschutz ist zus\u00e4tzlich rechtlich zu beachten und wird nicht als allgemeiner ZVG-Verteilungsalgorithmus erfunden.")
 ergebnis
}
